-- Guia "Barcelona em 4 dias: ingressos marcados da Sagrada Família e do Park Güell" (rascunho). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/barcelona-em-4-dias.json.
-- Entra como rascunho: publique pelo painel (/admin-blog.html) depois de conferir a pré-visualização.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('c86ca383-d4a8-4e84-a20a-8c250a0bea53', 'barcelona-em-4-dias', 'draft', 'europa', 'Barcelona em 4 dias: ingressos marcados da Sagrada Família e do Park Güell', 'ingressos marcados', 'Roteiro de Barcelona em 4 dias com a Sagrada Família e o Park Güell em horário marcado, transporte, taxa turística, bate-volta a Montserrat, valores em euro e em reais e o guia em PDF para baixar de graça.', 'Na Sagrada Família e no Park Güell o ingresso tem dia e horário, e quem chega atrasado perde a entrada. O roteiro encaixa cada reserva num dia, e o guia completo vai no celular.', 'Barcelona', NULL, '/assets/blog/barcelona-4-dias.jpg', '/assets/blog/barcelona-4-dias-m.jpg', 'As torres da Sagrada Família vistas de um lago cercado de árvores, com o céu azul e o sol baixo ao fundo', 0, '[{"t":"pdf","href":"/guias/barcelona-em-4-dias.pdf","note":"PDF de 16 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"Na Sagrada Família e no Park Güell **o ingresso tem dia e horário**. Compre antes de embarcar, só nos sites oficiais. No Park Güell, quem chega mais de 30 minutos depois do horário perde a entrada. Este roteiro encaixa cada reserva num dia e deixa o resto livre: **Bairro Gótico e Rambla, Eixample e Sagrada Família, Park Güell e Montjuïc, e Montserrat**."},{"t":"tip","items":["**Feche as datas da viagem e compre a Sagrada Família e o Park Güell primeiro.**","**Chegue com folga ao horário marcado,** com o ingresso no celular.","**Confira valores e horários na véspera,** nos sites oficiais listados no fim da página."],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"Bairro Gótico e Rambla","label":"Dia 1"},{"t":"p","text":"Plaça de Catalunya, La Rambla, o Mercado da Boqueria, a Catedral e o mar da Barceloneta no fim do dia."},{"t":"img","src":"/assets/blog/barcelona-gotico.jpg","alt":"Passarela neogótica entre dois prédios de pedra no Bairro Gótico de Barcelona, vista de baixo, com um arco aberto para o céu","caption":"Uma passarela do Bairro Gótico.","credit":"Foto: Jeffrey Eisen / Pexels","w":1000,"h":666},{"t":"ul","items":["**Manhã, Plaça de Catalunya e La Rambla:** comece na praça central e desça a avenida de pedestres até o mar. É o trecho mais cheio da cidade: cuide do celular e da carteira.","**Almoço, Mercado da Boqueria:** mercado coberto ao lado da Rambla, bom para sucos e petiscos. Os preços perto da entrada tendem a ser mais altos (observação da Rota Certa).","**Tarde, Catedral e Bairro Gótico:** perca-se nas ruas estreitas de pedra ao redor da catedral. Visita ao interior e horários: confirme no site da catedral.","**Fim da tarde, Barceloneta:** caminhe até a praia da Barceloneta para ver o dia acabar à beira-mar. Jante no bairro."]},{"t":"img","src":"/assets/blog/barcelona-boqueria.jpg","alt":"Banca de frutas e verduras do Mercado da Boqueria, com tomates, abacaxis e bananas expostos","caption":"Uma banca do Mercado da Boqueria.","credit":"Foto: AXP Photography / Pexels","w":1000,"h":666},{"t":"tip","items":["O site do museu lista entrada grátis no primeiro domingo do mês e, no inverno, na quinta à tarde, sempre com reserva antecipada. Fecha às segundas. Confirme o horário da quinta no site."],"title":"Museu Picasso: entrada grátis com reserva"},{"t":"tip","items":["**Grátis:** La Rambla, as ruas do Gótico e a praia da Barceloneta. **Opcional:** Museu Picasso, nas horas grátis.","**Estimativa da Rota Certa, não é dado oficial:** cerca de 6 horas nas atrações e cerca de 4 km a pé, tudo plano. Esforço baixo."],"title":"Para planejar o Dia 1"},{"t":"p","text":"[Abrir a rota a pé do Dia 1 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Pla%C3%A7a%20de%20Catalunya%2C%20Barcelona&waypoints=Mercat%20de%20la%20Boqueria%2C%20Barcelona%7CCatedral%20de%20Barcelona&destination=Platja%20de%20la%20Barceloneta%2C%20Barcelona&travelmode=walking)"},{"t":"passeio","busca":"Bairro Gótico Barcelona passeio a pé","title":"Passeios no Bairro Gótico"},{"t":"h","text":"Eixample e Sagrada Família","label":"Dia 2"},{"t":"p","text":"A Sagrada Família de manhã, com horário marcado, e a avenida das casas de Gaudí à tarde."},{"t":"img","src":"/assets/blog/barcelona-sagrada-familia.jpg","alt":"Torres da Sagrada Família vistas de baixo, com detalhes da pedra esculpida e o céu azul ao fundo","caption":"As torres da Sagrada Família, vistas de baixo.","credit":"Foto: Diana Nguyen / Pexels","w":1000,"h":666},{"t":"ul","items":["**Manhã, Sagrada Família:** chegue 15 minutos antes do horário marcado. Leve documento com foto e o ingresso no celular. O horário de funcionamento muda por estação: confirme no site oficial.","**Almoço, perto da basílica:** os restaurantes ao redor da basílica são turísticos (observação da Rota Certa). Caminhe duas ou três quadras e procure menus do dia nas ruas laterais.","**Tarde, Casa Batlló:** na Passeig de Gràcia, a fachada colorida se vê de graça da calçada. A visita por dentro é paga e pede reserva: confirme valores no site oficial.","**Fim da tarde, Casa Milà (La Pedrera):** a poucos minutos a pé da Casa Batlló. Do lado de fora, a fachada ondulada é o destaque."]},{"t":"tip","items":["**Ingresso básico (basílica e museu):** € 26 (cerca de R$ 160). **Com as torres:** € 36 (cerca de R$ 221).","O ingresso vale só para o horário escolhido: quem chega atrasado pode não entrar. Compre só no site oficial."],"title":"Sagrada Família: ingresso com dia e horário"},{"t":"img","src":"/assets/blog/barcelona-casa-batllo.jpg","alt":"Fachada colorida e ondulada da Casa Batlló, de Gaudí, vista de baixo, sob um céu azul","caption":"A fachada da Casa Batlló, na Passeig de Gràcia.","credit":"Foto: AXP Photography / Pexels","w":1000,"h":666},{"t":"tip","items":["**Grátis:** as fachadas da Casa Batlló e da Casa Milà, por fora. **Opcional:** torres da Sagrada Família ou visita às casas.","**Estimativa da Rota Certa, não é dado oficial:** cerca de 2 horas na basílica e cerca de 3 km a pé. Esforço baixo."],"title":"Para planejar o Dia 2"},{"t":"p","text":"[Abrir a rota do Dia 2 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Casa%20Batll%C3%B3%2C%20Barcelona&waypoints=Casa%20Mil%C3%A0%2C%20Barcelona&destination=Sagrada%20Fam%C3%ADlia%2C%20Barcelona&travelmode=transit)"},{"t":"passeio","busca":"Sagrada Família Barcelona","title":"Passeios na Sagrada Família e no Eixample"},{"t":"h","text":"Park Güell e Montjuïc","label":"Dia 3"},{"t":"p","text":"O Park Güell cedo, com horário marcado, e o pôr do sol no alto de Montjuïc."},{"t":"img","src":"/assets/blog/barcelona-park-guell.jpg","alt":"Vista do Park Güell, com o banco de mosaicos coloridos, as casinhas de Gaudí e a cidade ao fundo","caption":"O Park Güell, com o banco de mosaicos e a cidade ao fundo.","credit":"Foto: AXP Photography / Pexels","w":1000,"h":666},{"t":"ul","items":["**Manhã, Park Güell:** escolha um horário cedo: o parque enche ao longo do dia (observação da Rota Certa). Chegue 15 minutos antes e leve o ingresso no celular. A subida é em ladeira.","**Almoço, bairro de Gràcia:** desça a pé ou de transporte público até Gràcia, bairro de praças e cafés, com menos turistas que o centro (observação da Rota Certa).","**Fim da tarde, Montjuïc:** a colina sobre o porto tem mirantes com vista de toda a cidade. Boa hora para ver o sol se pôr."]},{"t":"tip","items":["**Ingresso geral:** € 18 (cerca de R$ 111), só com horário.","Você tem 30 minutos depois do horário para entrar. Depois disso, perde a entrada. Dentro, fica o tempo que quiser, mas não pode sair e voltar. Entradas de turistas das 9h30 às 17h30."],"title":"Park Güell: 30 minutos de tolerância"},{"t":"tip","items":["**Use calçado fechado e leve água:** os dois lugares têm ladeiras longas. É uma dica da Rota Certa.","**Grátis:** mirantes e jardins de Montjuïc. **Opcional:** Castelo de Montjuïc ou museus da colina.","**Estimativa da Rota Certa, não é dado oficial:** cerca de 2 horas no parque e 3 horas em Montjuïc. Esforço moderado: ladeiras."],"title":"Para planejar o Dia 3"},{"t":"p","text":"[Abrir a rota do Dia 3 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Park%20G%C3%BCell%2C%20Barcelona&destination=Montju%C3%AFc%20Castle%2C%20Barcelona&travelmode=transit)"},{"t":"passeio","busca":"Park Güell Barcelona","title":"Passeios no Park Güell e em Montjuïc"},{"t":"h","text":"Montserrat, bate-volta de trem","label":"Dia 4"},{"t":"p","text":"O mosteiro no meio de uma montanha de rochas, a cerca de 90 minutos de Barcelona."},{"t":"img","src":"/assets/blog/barcelona-montserrat.jpg","alt":"Mosteiro de Montserrat aos pés de montanhas de rochas arredondadas, com árvores, céu azul e nuvens","caption":"O mosteiro de Montserrat, aos pés da montanha.","credit":"Foto: Bas Linders / Pexels","w":1000,"h":666},{"t":"ul","items":["**Cedo, trem na Plaça d''Espanya:** o trem da linha R5 leva cerca de 1 hora até Monistrol de Montserrat. De lá, a cremalheira sobe a montanha em cerca de 20 minutos. O site oficial informa trens a cada hora.","**Manhã e tarde, mosteiro e basílica:** visite a basílica e caminhe pelos mirantes. Com o bilhete combinado, o acesso à basílica está incluído.","**Fim da tarde, volta a Barcelona:** confira o último trem de volta antes de subir. O trem comum de volta e a cremalheira podem ser usados até uma semana depois da primeira validação (conforme o site oficial)."]},{"t":"tip","items":["**Trans Montserrat:** a partir de € 50 (cerca de R$ 307), com o transporte e o acesso à basílica.","**Tot Montserrat:** a partir de € 71,50 (cerca de R$ 440), com o museu e o almoço também.","Preços e horários variam por época: confirme na compra, no site da [Cremallera de Montserrat](https://www.cremallerademontserrat.cat/)."],"title":"Bilhete combinado de Montserrat"},{"t":"tip","items":["**Leve um casaco:** na montanha faz mais frio e venta mais que na cidade (observação da Rota Certa).","**Grátis:** trilhas e mirantes ao redor do mosteiro. **Opcional:** funiculares e museu.","**Estimativa da Rota Certa, não é dado oficial:** cerca de 5 horas na montanha. Esforço moderado."],"title":"Para planejar o Dia 4"},{"t":"p","text":"[Abrir a rota do Dia 4 no Google Maps](https://www.google.com/maps/dir/?api=1&origin=Pla%C3%A7a%20Espanya%2C%20Barcelona&destination=Monistrol%20de%20Montserrat&travelmode=transit)"},{"t":"passeio","busca":"Montserrat bate-volta Barcelona","title":"Passeios a Montserrat"},{"t":"h","text":"Metrô, taxa turística e tomada","label":"Na prática"},{"t":"ul","items":["**Metrô e T-casual:** bilhete simples, € 2,90 (cerca de R$ 18). T-casual de 1 zona, 10 viagens: € 13 (cerca de R$ 80), com até 3 transferências em 75 minutos. Ela não vale nas estações Aeroport T1 e T2 da linha L9 Sul.","**Do aeroporto e o Hola BCN:** o bilhete de metrô do aeroporto custa € 5,90 (cerca de R$ 36). O cartão Hola BCN começa em € 12,50 (cerca de R$ 77) e inclui a ida e a volta de metrô ao aeroporto. Tabela por número de dias: confirme no site.","**Taxa turística, paga no hotel:** desde 1º de abril de 2026, a soma por pessoa e por noite é de cerca de € 8,40 (R$ 52) em hotel 4 estrelas, € 9,50 (R$ 58) em apartamento turístico e € 12 (R$ 74) em 5 estrelas. Cobrada nas primeiras noites da estada, com isenção para menores de 16 anos. Valores por categoria: confirme com o hotel.","**Segurança:** no metrô e na Rambla, mochila na frente e celular guardado. É uma dica da Rota Certa.","**Tomada e voltagem:** a Espanha usa 230 V e tomadas de pinos redondos (tipos C e F). Plugue brasileiro de três pinos não encaixa: leve adaptador."]},{"t":"h","text":"Documentos e checklist","label":"Antes de ir"},{"t":"ul","items":["**Passaporte, sem visto para turismo:** brasileiro não precisa de visto para turismo de até 90 dias no espaço Schengen. O passaporte deve valer 3 meses além da saída prevista.","**Dinheiro e passagem de volta:** a Espanha pode pedir cerca de € 122 por dia de estada, com mínimo de € 1.098,90 por pessoa, em dinheiro ou cartão com extrato. A passagem de volta é exigida.","**EES e ETIAS:** desde 10/4/2026, a fronteira registra digitais e foto (EES). O ETIAS está previsto para o último trimestre de 2026, sem data exata e com taxa de € 20. Use só o site oficial."]},{"t":"tip","items":["Passaporte válido por 3 meses além da volta.","Passagem de volta e reserva de hotel.","Seguro viagem com cobertura médica.","Sagrada Família e Park Güell comprados.","Ingressos salvos no celular.","Trem para Montserrat, ida e volta."],"title":"Checklist"},{"t":"tip","items":["Sagrada Família (básico) e Park Güell somam € 44 (cerca de R$ 271). Com as torres, € 54 (cerca de R$ 332).","Reais pela PTAX de venda do Banco Central de 26/10/2026 (€ 1 = R$ 6,15), que oscilou muito nos últimos dias: reconfira antes de fechar. No cartão entram o IOF e o câmbio do seu banco."],"title":"Quanto custa, pagando tudo"},{"t":"pdf","href":"/guias/barcelona-em-4-dias.pdf","note":"Leve o roteiro, as rotas e o orçamento no celular. Grátis, sem cadastro."},{"t":"tip","items":["**Sagrada Família:** [preços](https://sagradafamilia.org/en/prices) e [regras de venda](https://sagradafamilia.org/en/rules-and-conditions-of-sale). **Park Güell:** [preços e horários](https://parkguell.barcelona/en/planning-your-visit/prices-and-times) e [compra](https://parkguell.barcelona/en/buy-tickets).","**Metrô:** [T-casual, ATM](https://www.atm.cat/titols-i-tarifes/t-casual), [tarifas, TMB](https://static-web.tmb.cat/en/barcelona-fares-metro-bus) e [Hola BCN](https://www.holabarcelona.com/en/travel-card).","**Taxa turística:** [Catalan News, conforme a Llei 2/2026 da Catalunha](https://www.catalannews.com/society-science/item/new-tourist-tax-comes-into-force-in-barcelona). **Montserrat:** [Cremallera de Montserrat](https://www.cremallerademontserrat.cat/). **Museu Picasso:** [horários e entradas](https://museupicassobcn.cat/en/plan-your-visit/buy-tickets-and-opening-hours).","**Entrada na Espanha:** [Ministério do Interior](https://www.interior.gob.es/opencms/es/servicios-al-ciudadano/tramites-y-gestiones/extranjeria/regimen-general/entrada-requisitos-y-condiciones/), [EES e ETIAS](https://home-affairs.ec.europa.eu/news/main-differences-between-ees-and-etias-what-travellers-need-know-2026-04-28_en) e [taxa do ETIAS](https://home-affairs.ec.europa.eu/news/european-travel-authorisation-etias-will-cost-eur-20-2025-07-17_en).","**Outras:** [tomadas, IEC](https://www.iec.ch/world-plugs) e [câmbio, Banco Central](https://www.bcb.gov.br/estabilidadefinanceira/historicocotacoes)."],"title":"Fontes oficiais, conferidas em 27/10/2026"},{"t":"tip","items":["**Horários da Sagrada Família por estação:** vêm de páginas de regras e perguntas frequentes, em parte antigas. Confira no site oficial antes de comprar.","**Tabela do Hola BCN por número de dias:** só o \"a partir de € 12,50\" é oficial.","**Taxa turística por categoria:** os totais vêm de imprensa, e o texto da lei não foi lido. Confirme com o hotel.","**Horário da quinta grátis do Museu Picasso:** as fontes divergem.","**Casa Batlló, Casa Milà e Catedral:** valores não incluídos. **Trem de Montserrat:** preço e horários variam por época."],"title":"O que este guia não informa"},{"t":"p","text":"Preços, horários e regras mudam: confira nas fontes acima antes de ir. As estimativas de tempo e esforço e as dicas marcadas como da Rota Certa são recomendações nossas, não dados oficiais."},{"t":"p","text":"Foto de capa: Mehmet Turgut Kirkgoz / Pexels."},{"t":"whatsapp"},{"t":"p","text":"Quer montar o roteiro da viagem inteira? Use o [Planner grátis da Rota Certa](https://rotacertapassagens.com/#/planner)."},{"t":"contato"},{"t":"afiliado"}]', 8);
